const e=document.querySelector(".header"),t=document.querySelector("#recent-work-heading"),o=document.querySelector("#recent-work-heading .section-title"),l=document.querySelector("#intro-blurb"),s=document.querySelector(".logo");export default()=>window.addEventListener("scroll",()=>{window.requestAnimationFrame(()=>{const c=window.scrollY>100;t.classList.toggle("scrolled",c),e.classList.toggle("scrolled",c),s.classList.toggle("scrolled",c),l.classList.toggle("hide-intro",c);const r=t.getBoundingClientRect().top;o.classList.toggle("underline",r>=35),o.classList.toggle("highlight",r<=35)})});